<script setup>
import { reactive, watch } from 'vue';
import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue';
import { reminderDraft } from '../domain/reminders-view.mjs';
const props = defineProps({ record: { type: Object, default: null }, editing: Boolean, saving: Boolean, error: { type: String, default: '' }, safeAreaStyle: { type: Object, default: () => ({}) } }); const emit = defineEmits(['cancel', 'save']); const draft = reactive({ ...reminderDraft(props.record) }); watch(() => props.record, (record) => Object.assign(draft, reminderDraft(record)), { deep: true });
const dateTypes = Object.freeze([{ value: 'birthday', label: 'Sinh nhật' }, { value: 'founding', label: 'Thành lập' }, { value: 'anniversary', label: 'Kỷ niệm' }, { value: 'other', label: 'Khác' }]); const recurringOptions = Object.freeze([{ value: 1, label: 'Hằng năm' }, { value: 0, label: 'Một lần' }]); function submit() { emit('save', { ...draft }); }
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar :title="editing ? 'Sửa ngày nhắc' : 'Thêm ngày nhắc'" @back="emit('cancel')" /><form class="min-h-0 flex-1 overflow-y-auto" @submit.prevent="submit"><div class="mds-mobile-gutter-x space-y-4 py-4"><p v-if="error" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ error }}</p><label><span class="mb-1 block text-[13px] font-medium">Tiêu đề</span><MInput v-model="draft.title" required placeholder="Sinh nhật đối tác" /></label><label><span class="mb-1 block text-[13px] font-medium">Loại sự kiện</span><MSelect v-model="draft.date_type" :options="dateTypes" /></label><label><span class="mb-1 block text-[13px] font-medium">Ngày sự kiện</span><MInput v-model="draft.event_date" type="date" required /></label><label><span class="mb-1 block text-[13px] font-medium">Lặp lại</span><MSelect v-model="draft.recurring" :options="recurringOptions" /></label><label><span class="mb-1 block text-[13px] font-medium">Báo trước (ngày)</span><MInput v-model="draft.lead_days" type="number" /></label><label><span class="mb-1 block text-[13px] font-medium">Đối tượng</span><MInput v-model="draft.subject_name" placeholder="Người hoặc cơ quan liên quan" /></label><label><span class="mb-1 block text-[13px] font-medium">Ghi chú</span><MTextarea v-model="draft.note" :rows="4" placeholder="Thông tin cần lưu ý" /></label></div><footer class="flex gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton type="button" variant="neutral" class="flex-1 [&]:h-[var(--mds-mobile-touch-target)]" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton type="submit" variant="primary" class="flex-1 [&]:h-[var(--mds-mobile-touch-target)]" :loading="saving">{{ editing ? 'Lưu' : 'Tạo' }}</MButton></footer></form></section></template>
